function validate([heightMap]) {
  if (!Array.isArray(heightMap) || heightMap.length < 1 || heightMap.length > 200) return 'heightMap needs 1 to 200 rows.';
  const n = Array.isArray(heightMap[0]) ? heightMap[0].length : 0;
  if (n < 1 || n > 200) return 'Each row needs 1 to 200 values.';
  for (const row of heightMap) {
    if (!Array.isArray(row) || row.length !== n) return 'Every row must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 0 || v > 20000)) return 'Each height is an integer between 0 and 20000.';
  }
  return null;
}

