function trapRainWater(heightMap) {
  const rows = heightMap.length;
  const cols = heightMap[0].length;
  let highest = 0;
  for (const row of heightMap) {
    highest = Math.max(highest, ...row);
  }
  const buckets = Array.from({ length: highest + 1 }, () => []);
  const visited = Array.from({ length: rows }, () => new Array(cols).fill(false));

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (r === 0 || c === 0 || r === rows - 1 || c === cols - 1) {
        visited[r][c] = true;
        buckets[heightMap[r][c]].push([r, c]);
      }
    }
  }

  let water = 0;
  for (let level = 0; level <= highest; level++) {
    const bucket = buckets[level];
    while (bucket.length > 0) {
      const [r, c] = bucket.pop();
      for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
        if (nr >= 0 && nc >= 0 && nr < rows && nc < cols && !visited[nr][nc]) {
          visited[nr][nc] = true;
          water += Math.max(0, level - heightMap[nr][nc]);
          buckets[Math.max(level, heightMap[nr][nc])].push([nr, nc]);
        }
      }
    }
  }
  return water;
}

