function trapRainWater(heightMap) {
  // Start every inner cell full to the brim and let water drain until nothing changes.
  const m = heightMap.length, n = heightMap[0].length;
  const top = Math.max(...heightMap.flat());
  const surface = heightMap.map((row, i) => row.map((h, j) => (i === 0 || j === 0 || i === m - 1 || j === n - 1) ? h : top));
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 1; i < m - 1; i++) {
      for (let j = 1; j < n - 1; j++) {
        const lowest = Math.min(surface[i - 1][j], surface[i + 1][j], surface[i][j - 1], surface[i][j + 1]);
        const next = Math.max(heightMap[i][j], lowest);
        if (next < surface[i][j]) { surface[i][j] = next; changed = true; }
      }
    }
  }
  let total = 0;
  for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) total += surface[i][j] - heightMap[i][j];
  return total;
}

