function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const m = large ? int(90, 100) : rand() < 0.15 ? int(1, 2) : int(3, 6);
  const n = large ? int(90, 100) : rand() < 0.15 ? int(1, 2) : int(3, 6);
  const top = large ? 20000 : [3, 6, 20][int(0, 2)];
  const style = int(0, 2);
  const cm = (m - 1) / 2, cn = (n - 1) / 2;
  return [Array.from({ length: m }, (_, i) => Array.from({ length: n }, (_, j) => {
    if (style === 0) return int(0, top);
    // A bowl (or a ridge) with noise, so that deep ponds and dry slopes both appear.
    const ring = Math.max(Math.abs(i - cm), Math.abs(j - cn)) / Math.max(1, cm, cn);
    const shape = style === 1 ? ring : 1 - ring;
    return Math.min(top, Math.max(0, Math.round(shape * top) + int(-Math.ceil(top / 4), Math.ceil(top / 4))));
  }))];
}
